// =====================================================================
//  All-in Aloe plot script: Blastberry tech
//
//  Only acts in steps whose layout grows All-in Aloe. Nothing is planted.
//
//  Every All-in Aloe is harvested with +30% yield and Immunity, as if a
//  Blastberry had been put next to it just before the harvest, and 1 Magic
//  Jellybean leaves the inventory for it (the placed Jellybean you break to
//  make room). The built-in harvest still decides when each aloe is
//  harvested. Aloes the step change would clear are harvested first so they
//  get the tech too.
// =====================================================================

const ALOE = "all_in_aloe";
const JB = "magic_jellybean";
const BB_EFFECTS = ["immunity", "improved_harvest_boost"];

let aloeStep = false;   // does this step grow All-in Aloe?
let tally = { aloesHarvested: 0, aloesWithTech: 0, jellybeansSpent: 0 };
let warned = {};

function warnOnce(id, text) {
  if (warned[id]) return;
  warned[id] = true;
  warn(text);
}

function capture() {
  aloeStep = plot.layout.targets.some((t) => t.mutation === ALOE);
}

// The aloes being harvested hold the Blastberry's effects for that moment only
// (forced effects), and 1 Magic Jellybean per aloe is placed on the aloe's empty
// cell and broken straight away, which spends it without counting as a harvest.
function withBlastberry(run) {
  const before = forcedEffects[ALOE] ?? [];
  forceEffects(ALOE, [...before, ...BB_EFFECTS]);
  run();
  if (before.length) forceEffects(ALOE, before);
  else unforceEffects(ALOE);
}

function spendJellybean(r, c) {
  if (!plot.place(JB, r, c)) return false;
  plot.breakAt(r, c);
  tally.jellybeansSpent++;
  return true;
}

/** The built-in harvest phase, with the Blastberry effects on every aloe it takes. */
function harvestWithTech() {
  const before = plot.spawns(ALOE).map((p) => ({ id: p.id, row: p.row, col: p.col }));
  const ready = plot.spawns(ALOE).filter((p) => p.stage >= 4).length;
  if (!ready || (!config.allowMutationDebt && inventory.get(JB) < ready)) {
    if (ready) warnOnce("jbstock", `Cycle ${cycle}: not enough Magic Jellybeans for the Blastberry tech on every aloe; this harvest goes without it.`);
    plot.runPhase("harvest");
    return;
  }
  withBlastberry(() => plot.runPhase("harvest"));
  // 1 Jellybean for each aloe that was there before and is gone now.
  const still = {};
  for (const p of plot.spawns(ALOE)) still[p.id] = true;
  for (const a of before) {
    if (still[a.id]) continue;
    tally.aloesHarvested++;
    tally.aloesWithTech++;
    spendJellybean(a.row, a.col);
  }
}

/** The step changes this session: harvest the aloes it would clear, with the tech. */
function harvestBeforeStepChange() {
  const due = plot.spawns(ALOE).filter((p) => p.stage >= 4);
  if (!due.length) return;
  const n = config.allowMutationDebt ? due.length : Math.min(due.length, inventory.get(JB));
  if (n < due.length) warnOnce("jbstock2", `Cycle ${cycle}: not enough Magic Jellybeans for the Blastberry tech; some aloes are harvested without it.`);
  if (n) {
    withBlastberry(() => {
      for (const a of due.slice(0, n)) {
        const r = a.row;
        const c = a.col;
        if (a.harvest()) {
          tally.aloesHarvested++;
          tally.aloesWithTech++;
          spendJellybean(r, c);
        }
      }
    });
  }
  for (const a of due.slice(n)) if (a.harvest()) tally.aloesHarvested++;
}

// ---- Hooks ----
function onStart() {
  capture();
}

function onStepChange(e) {
  capture();
}

function onSession() {
  if (!aloeStep) return;
  const to = plot.pending ?? plot.exitDue();
  if (to && to !== plot.step.id) harvestBeforeStepChange();
  harvestWithTech();
}

function afterSession() {
  const p = `Plot ${plot.id}: `;
  metric(p + "aloes harvested", tally.aloesHarvested);
  metric(p + "aloes harvested with +30% and immunity", tally.aloesWithTech);
  metric(p + "Magic Jellybeans spent on the Blastberry tech", tally.jellybeansSpent);
}

